window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-43001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγέλλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 795 na letra φ · nº geral 43001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. chicote ; látego.</p></section></article>\n<article id=\"entry-dgp-43002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγελλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 796 na letra φ · nº geral 43002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chicotear; flagelar. 〈φραγέλλιον〉</p></section></article>\n<article id=\"entry-dgp-43003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 797 na letra φ · nº geral 43003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 pas. de φράσσω.</p></section></article>\n<article id=\"entry-dgp-43004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 798 na letra φ · nº geral 43004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tapume; paliçada; fortificação; defesa 2 abrigo. 〈φράσσω〉</p></section></article>\n<article id=\"entry-dgp-43005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 799 na letra φ · nº geral 43005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de tapar; oclusão 2 sebe; paliçada 3 parapeito (de ponte) 4 fortificação 5 bíbl. cerca; muro. 〈φράσσω〉</p></section></article>\n<article id=\"entry-dgp-43006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 800 na letra φ · nº geral 43006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φράσσω.</p></section></article>\n<article id=\"entry-dgp-43007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 801 na letra φ · nº geral 43007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prudente; sensato; astuto, perspicaz. 〈φράζω〉</p></section></article>\n<article id=\"entry-dgp-43008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραδμοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 802 na letra φ · nº geral 43008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prudência; sensatez. 〈φράδμων〉</p></section></article>\n<article id=\"entry-dgp-43009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράδμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 803 na letra φ · nº geral 43009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος prudente; sensato. 〈φράζω〉</p></section></article>\n<article id=\"entry-dgp-43010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράζεο</h1><div class=\"entry-meta\"><span>DGP · ordem 804 na letra φ · nº geral 43010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, contr., φράζευ 2ª sing. imper. pres., φράζετο 3ª sing. impf., formas méd. poét. de φράζω.</p></section></article>\n<article id=\"entry-dgp-43011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράζω</h1><div class=\"entry-meta\"><span>DGP · ordem 805 na letra φ · nº geral 43011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φράσω, aor. ἔφρασα, perf. πέφρακα) 1 indicar pela palavra ou por um sinal; orientar; mostrar algo, ac., a alguém, dat.: ἐς χῶρον ὃν φράσε Κίρκη hom. no lugar que Circe indicou, φράσσατέ μοι δόμους pínd. indica-me o palácio, φωνῆσαι οὐκ εἶχε... τῇ δὲ χειρὶ ἔφραζε ἐλθεῖν her. não tinha como falar, mas fez sinal com a mão para que viesse 2 explicar; expor; contar algo, ac. ou or. inf. ou conj. (ὅτι, ὡς), a alguém, ac. ou dat. ou πρός e ac.; falar de algo ou alguém, gen. ou περί, ἐπί e gen.: ἔφραζε Λακεδαιμονίοσσι πᾶν τὸ πρῆγμα her. contou todo o caso aos lacedemônios, φράζε πρὸς ἡμᾶς ὅ τι χρῄζεις ar. dize-nos o que está precisando, φράσον δ᾽ ἅπερ γ᾽ ἔλεξας sóf. explica o que disseste, τῆς μητρὸς ἥκω τῆς ἐμῆς φράσων ἐν οἷς νῦν ἐστιν sóf. estou aqui para falar de como minha mãe está agora, τοῦτο φράζει ὅτι isto significa que 3 dizer; mandar; ordenar a alguém, dat., algo, inf.: τοῖς τ᾽ ἀνθρώποισι φράσον σιγᾶν ar. ordena aos homens que façam silêncio 4 aconselhar; sugerir ♦ méd. jôn. e poét. (fut. φράσομαι, aor. ἐφρασάμην, 3a sing. ép. φράσατο e φράσσατο, perf. πέφρασμαι) 5 ter em mente; pensar; ter a opinião: φ. ἀμφίς hom. ser de opinião diferente 6 pensar; considerar; meditar: φρ. θυμῷ ou ἐνὶ φρεσί ou μετὰ φρεσίν hom. refletir em seu coração, φρ. βουλήν ou μῆτιν hom. meditar um desígnio 7 cogitar; tramar; idear algo, ac., contra alguém, dat.: φράσσατο Πατρόκλῳ μέγα ἠρίον hom. cogitou construir um grande túmulo para Pátroclo 8 notar; observar; aperceber-se de, ac. ou gen.: τὸν δὲ φράσατο προσίοντα hom. notou que ele se aproximava 9 prestar atenção em; vigiar, ac. ou πρός e ac. 10 estar atento a; tomar cuidado com algo: φράζευ κύνα ar. cuidado com o cão! φράσσαι κυναλώπεκα, μή σε δολώσῃ ar. cuidado com o cão-raposa, cuidado para ele não te enganar.</p></section></article>\n<article id=\"entry-dgp-43012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράξαι</h1><div class=\"entry-meta\"><span>DGP · ordem 806 na letra φ · nº geral 43012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2a sing. imper. méd. de φράσσω.</p></section></article>\n<article id=\"entry-dgp-43013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 807 na letra φ · nº geral 43013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de expressar pela palavra; modo de falar, de se expressar; elocução 2 caráter expressivo da palavra; estilo; expressão 3 discurso; texto. 〈φράζω〉</p></section></article>\n<article id=\"entry-dgp-43014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 808 na letra φ · nº geral 43014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. φράττω (fut. φράξω, aor. ἔφραξα, perf. desus., m.-q.-perf. ἐπεφράκειν; pas. fut. φραγήσομαι, aor.1 ἐφράχθην, aor.2 ἐφράγην, perf. πέφραγμαι) 1 apertar uma coisa, ac., contra outra, dat.: φρ. δόρυ δουρί, σάκος σάκει hom. comprimir lança contra lança, escudo contra escudo, φρ. τὰ γέρρα her. apertar os escudos uns contra os outros 2 encher: φρ. χεῖρα ἔρνεσιν pínd. encher a mão de ramos 3 obstruir; tapar: φρ. τοὺς ἔσπλους tuc. obstruir o ingresso nos portos 4 construir barricadas 5 cobrir; proteger: φρ. δέμας ὅπλοισι ésql. proteger o corpo sob uma armadura ♦ méd. 6 tampar, vedar em si mesmo: φρ. τὰ ὦτα κηρῷ luc. tampar as orelhas com cera 7 tampar para si; fechar; proteger: φρ. νῆας ἕρκει χαλκείῳ hom. proteger os barcos com muralha de bronze, i.e, com pessoas armadas 8 guarnecer; fortificar (portas, muralhas) ♦ 9 intr. rodear-se de fortificações; defender-se contra algo ou alguém, πρός, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-43015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραστήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 809 na letra φ · nº geral 43015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indicador; intérprete; guia. 〈φράζω〉</p></section></article>\n<article id=\"entry-dgp-43016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 810 na letra φ · nº geral 43016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que explica; que indica; indicativo; expressivo, gen. 2 referente à palavra; da palavra 3 capaz de expressar; eloquente (pessoa) ♦ τὸ φραστικόν 4 facilidade de expressão; eloquência. 〈φράζω〉</p></section></article>\n<article id=\"entry-dgp-43017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράτηρ, ερος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 811 na letra φ · nº geral 43017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 membro de uma fratria 2 pl. membros de uma mesma fratria.</p></section></article>\n<article id=\"entry-dgp-43018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράτρα,</h1><div class=\"entry-meta\"><span>DGP · ordem 812 na letra φ · nº geral 43018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. φρήτρη, ης (ἡ) = φρατρία.</p></section></article>\n<article id=\"entry-dgp-43019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρατρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 813 na letra φ · nº geral 43019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. 1 em Hom. clã; família 2 em Atenas, fratria, subdivisão política e religiosa da tribo (φυλή) e constituída de trinta famílias (γένη) 3 em Roma, cúria. 〈φράτηρ〉</p></section></article>\n<article id=\"entry-dgp-43020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρατρίαρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 814 na letra φ · nº geral 43020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chefe ou presidente de uma fratria. 〈φρατρία, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-43021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράττω</h1><div class=\"entry-meta\"><span>DGP · ordem 815 na letra φ · nº geral 43021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = φράσσω.</p></section></article>\n<article id=\"entry-dgp-43022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 816 na letra φ · nº geral 43022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φράτηρ.</p></section></article>\n<article id=\"entry-dgp-43023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρέαρ, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 817 na letra φ · nº geral 43023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 poço: ἡ περὶ τὸ φρέαρ ὄρχησις plut. a dança ao redor do poço, ref. a um perigo mal calculado, εἰς φρέατά τε καὶ πᾶσαν ἀπορίαν εἰσπίπτειν plat. cair num poço em poço e em todo tipo de aporia 2 cisterna; reservatório d’água 3 jarra para óleo novo.</p></section></article>\n<article id=\"entry-dgp-43024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεατιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 818 na letra φ · nº geral 43024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do poço; da cisterna. 〈φρέαρ〉</p></section></article>\n<article id=\"entry-dgp-43025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεῖαρ</h1><div class=\"entry-meta\"><span>DGP · ordem 819 na letra φ · nº geral 43025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = φρεάρ.</p></section></article>\n<article id=\"entry-dgp-43026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεναπατάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 820 na letra φ · nº geral 43026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. enganar. 〈φρεναπάτης〉</p></section></article>\n<article id=\"entry-dgp-43027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεναπάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 821 na letra φ · nº geral 43027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. enganador. 〈φρήν, ἀπατάω〉</p></section></article>\n<article id=\"entry-dgp-43028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 822 na letra φ · nº geral 43028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sensato; razoável; prudente. 〈φρήν, ἀραρίσκω〉</p></section></article>\n<article id=\"entry-dgp-43029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενιτιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 823 na letra φ · nº geral 43029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter uma forte emoção; delirar; estar louco. 〈φρενῖτις〉</p></section></article>\n<article id=\"entry-dgp-43030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενιτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 824 na letra φ · nº geral 43030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">φρενιτίαω.</p></section></article>\n<article id=\"entry-dgp-43031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενῖτις, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 825 na letra φ · nº geral 43031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. delírio; loucura; demência. 〈φρήν〉</p></section></article>\n<article id=\"entry-dgp-43032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενοβλαβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 826 na letra φ · nº geral 43032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem a razão prejudicada; louco. 〈φρήν, βλάπτω〉</p></section></article>\n<article id=\"entry-dgp-43033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενοδαλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 827 na letra φ · nº geral 43033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz perder a razão. 〈φρήν, δηλέομαι〉</p></section></article>\n<article id=\"entry-dgp-43034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 828 na letra φ · nº geral 43034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. conforme seu pensamento ou sentimento; espontaneamente; voluntariamente. 〈φρήν, -θεν〉</p></section></article>\n<article id=\"entry-dgp-43035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενομανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 829 na letra φ · nº geral 43035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com espírito extraviado; delirante, louco. 〈φρήν, μαίνομαι〉</p></section></article>\n<article id=\"entry-dgp-43036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενομόρως</h1><div class=\"entry-meta\"><span>DGP · ordem 830 na letra φ · nº geral 43036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. alucinadamente. 〈φρήν, μόρος〉</p></section></article>\n<article id=\"entry-dgp-43037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενοπληγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 831 na letra φ · nº geral 43037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que atinge o espírito; que alucina. 〈φρήν, πλήσσω〉</p></section></article>\n<article id=\"entry-dgp-43038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενόπληκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 832 na letra φ · nº geral 43038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem o espírito abalado; louco. 〈φρήν, πλήσσω〉</p></section></article>\n<article id=\"entry-dgp-43039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρενόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 833 na letra φ · nº geral 43039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φρενώσω, perf. pas. πεφρένωμαι) 1 fazer voltar à razão; tornar prudente ou sensato, ac. ♦ pas. 2 voltar à razão 3 orgulhar-se de, dat. 〈φρήν〉</p></section></article>\n<article id=\"entry-dgp-43040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεωρυχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 834 na letra φ · nº geral 43040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cavar um poço. 〈φρεωρύχος〉</p></section></article>\n<article id=\"entry-dgp-43041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεωρύχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 835 na letra φ · nº geral 43041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cava poço ou poços 2 próprio para cavar poço ♦ ὁ φρεωρύχος 3 poceiro. 〈φρέαρ, ὀρύσσω〉</p></section></article>\n<article id=\"entry-dgp-43042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρήν, φρενός</h1><div class=\"entry-meta\"><span>DGP · ordem 836 na letra φ · nº geral 43042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ἡ) 1 Medic. diafragma 2 pericárdio 3 membrana que envolve o fígado; peritônio 4 pl. vísceras; entranhas 5 poét. coração; alma; espírito, como sede dos sentimentos ou da vontade: ἐς φρένα θυμός ἀγέρθη hom. o sentimento voltou novamente à alma, διὰ φρενός no fundo do coração, ἐκ φρενός do coração, ἐν φρενὶ λαμβάνειν λόγον her. meditar o discurso, prestar-lhe atenção, κατὰ φρένα hom. no coração, κατὰ φρένα καὶ κατὰ θυμόν hom. no espírito e no coração, ὀρθᾷ φρενί pínd. com espírito reto, οὐδὲ ∆ιὸς πεῖθε φρένα hom. não persuadiu o espírito de Zeus 6 pl., razão; espírito, como sede da inteligência: τὸν νοῦν τῶν φρενῶν sóf. o pensamento de teu espírito, φρένας ἔχειν plut. ter inteligência, φρένας ἄφρων hom. desprovido de inteligência, φρεσὶν ἀγαθῇσι κεχρῆσθαι hom. ter o espírito são, ser sensato e honesto, ἐν φρεσὶ ποιεῖν ou ἐπὶ φρεσὶ τιθέναι hom. inspirar, sugerir a idéia, φρενῶν ἀφεστάναι sóf. estar alheio à razão, ἔσω φρενῶν sóf. no fundo do pensamento, ἔξω φρενῶν plut. fora de seu bom senso, φρενῶν ἀγαθῶν ἔρημος plut. ou φρενῶν κενός sóf. privado de razão, μετὰ φρεσὶ βάλλεσθαι hom. pensar, projetar, ἐνὶ φρεσὶ ἴδμεν hom. saber em seu espírito, ἐνὶ φρεσὶ θέσθαι hom. pôr no coração, i.e., tomar a peito, assumir com coragem, enfrentar, φρεσὶν ἔχειν hom. conservar no coração, no pensamento.</p></section></article>\n<article id=\"entry-dgp-43043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρήτρη</h1><div class=\"entry-meta\"><span>DGP · ordem 837 na letra φ · nº geral 43043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φράτρα.</p></section></article>\n<article id=\"entry-dgp-43044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρίκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 838 na letra φ · nº geral 43044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estremecimento; tremor 2 arrepio da pele, de medo ou de frio ou de febre 3 arrepio provocado pelo respeito à divindade; temor religioso; terror santo 4 agitação do mar, das águas. 〈φρίσσω〉</p></section></article>\n<article id=\"entry-dgp-43045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρικτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 839 na letra φ · nº geral 43045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que provoca calafrio; apavorante; terrível. 〈φρίσσω〉</p></section></article>\n<article id=\"entry-dgp-43046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρικώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 840 na letra φ · nº geral 43046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que faz estremecer; assustador; terrível 2 que infunde temor sagrado 3 acompanhado de calafrio (febre) ♦ τὸ φρικῶδες 4 Medic. o arrepio. 〈φρίξ, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-43047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φριμάσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 841 na letra φ · nº geral 43047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(animal) exalar um sopro ruidoso; bufar; fremir.</p></section></article>\n<article id=\"entry-dgp-43048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρίξ, φρικός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 842 na letra φ · nº geral 43048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitação do mar 2 eriçamento (dos pelos de um animal) 3 arrepio (de frio ou de medo).</p></section></article>\n<article id=\"entry-dgp-43049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φριξαύχην, χενος</h1><div class=\"entry-meta\"><span>DGP · ordem 843 na letra φ · nº geral 43049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que tem o pescoço cerdoso (golfinho). 〈φρίσσω, αὐχήν〉</p></section></article>\n<article id=\"entry-dgp-43050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρίσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 844 na letra φ · nº geral 43050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. φρίττω (fut. φρίξω, aor. ἔφριξα, perf. πέφρικα, com valor de pres.) 1 ser ou tornar-se hirto ou encrespado na superfície; encrespar-se; eriçar-se: φρίσσουσιν ἄρουραι hom. os campos se eriçam (de espigas), φάλαγγες ἔγχεσι πεφρικυῖαι hom. fileiras eriçadas de lanças, φιάλα χρυσῷ πεφρικυῖα pínd. taça com relevos em ouro 2 tremer; estremecer ao ver ou pensar em alguém ou algo, ac., πρός e ac. ou ὑπέρ e gen.: φρίσσοντες ὄμβροι pínd. chuvas que fazem tremer, φρίσσω δέ σε δερκομένη ésql. estremeço ao ver-te, τίς οὐκ ἂν ἔφριξε ποιῆσαι; dem. quem não estremeceu ao pensar em fazer? 3 fremir: ἔφριξ᾽ ἔρωτι sóf. fremiu de paixão 4 estremecer por temor religioso, por terror sagrado.</p></section></article>\n<article id=\"entry-dgp-43051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροιμιάζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 845 na letra φ · nº geral 43051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">προοιμιάζω.</p></section></article>\n<article id=\"entry-dgp-43052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροίμιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 846 na letra φ · nº geral 43052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">προοίμιον.</p></section></article>\n<article id=\"entry-dgp-43053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 847 na letra φ · nº geral 43053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φρονήσω, aor. ἐφρόνησα, perf. πεφρόνηκα) 1 ser sensato, sábio, prudente; pensar ou julgar com sabedoria; compreender; entender 2 ter no ânimo; alimentar; nutrir (algo), ac., por alguém, dat. 3 ter em mente; pensar algo, ac.; μέγα φρ. ter pensamentos elevados ou ser arrogante, devido a algo, ἐπί e dat., contra alguém, εἰς e ac.; μεγάλα φρ. ser presunçoso; μικρὸν φρ. ser medíocre ou pusilânime; ἧσσον ou ἔλασσον φρ. sentir-se inferior a alguém, gen. 4 pretender; ter a intenção de, inf. 5 pensar; considerar; levar em consideração 6 ter controle das próprias faculdades mentais; estar em seu juízo; ser lúcido 7 ter sensibilidade; sentir-se vivo 1 οἱ φρονοῦντες el. os que pensam, os sábios, ἡ ἡλικία τοῦ ἤδη φρονεῖν ésqn. a idade de já ter juízo, εἰ φρονῶν ἔπρασσον sóf. se tivesse feito conscientemente, φρονοῦσ᾽ ὅτι ἔργοις πεπονθὼς ῥήμασίν σ᾽ ἀμύνομαι sóf. compreendem que, atingido por atos, defendo-te com palavras, διέπεμπε δὲ πειρώμενος τῶν μαντηίων ὅ τι φρονέοιεν her. enviou legados a vários oráculos tentando saber o que eles pensavam 2 εἰ κέν τοι κείνη γε φίλα φρονέῃσ᾽ ἐνὶ θυμῷ hom. se ela nutrir no coração sentimentos de amizade por ti, ἄριστα φρ. τινί ar. querer o melhor para alguém, κακὰ φρονέουσι διαμπερὲς ἀλλήλοισιν hom. nutrem sem cessar hostilidades mútuas, πιστά τινι φρ. pínd. ser leal com alguém, εὖ ou καλῶς φρ. τινί ou εἴς τινα querer bem a alguém, εὖ φρονῶ τὰ σά sóf. tenho bons pensamentos no que se refere a ti 3 ἀγαθὰ φρ. hom. ter pensamentos corretos ou boas intenções, ἄριστα φρ. tuc. ter as melhores intenções, τυραννικὰ φρ. ar. ter em mente a tirania, τὰ σὰ φρ. her. ter os teus pensamentos, i.e., pensar como tu, φρ. τὰ Βρασίδου ar. ser partidário de Brásidas, ἀμφὶς φρ. hom. pensar diferentemente, ἄνδρες ἐπὶ παιδεύσει μέγα φρονοῦντες plat. homens envaidecidos de sua educação, ἐφ᾽ ἑαυτῷ μέγα φρ. tuc. ter orgulho de si mesmo, σφάλλω δ᾽ ὅσοι φρονοῦσιν εἰς ἡμᾶς μέγα eur. faço cair quantos são arrogantes conosco 4 αὔδα ὅ τι φρονέεις hom. fala o que tens em mente, ἄλλα φρονέειν καὶ ἄλλα λέγειν her. pensar uma coisa e dizer outra, φρονέω δὲ διακρινθήμεναι ἤδη Ἀργείους καὶ Τρῶας hom. pretendo que argivos e troianos resolvam já a contenda 5 φρόνησον, ὦ κασιγνήτη, πατὴρ ὡς νῷν ἀπεχθὴς δυσκλεής τ᾽ ἀπώλετο sóf. pensa, irmã, que nosso pai morreu odiado e sem glória 6 νῦν φρονῶ τότ᾽ οὐ φρονῶν eur. agora estou lúcido, naquele tempo não estava, εὖ φρ. eur. estar lúcido 7 μηδὲ ζῆν μηδὲ φρονεῖν plat. nem viver nem sentir-se vivo. 〈φρήν〉</p></section></article>\n<article id=\"entry-dgp-43054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 848 na letra φ · nº geral 43054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espírito; inteligência; pensamento 2 maneira de pensar; sentimento; propósito; intenção 3 grandeza d’alma; sentimentos elevados; nobreza de intenções; coragem 4 pl. projetos grandiosos; grandes aspirações 5 orgulho; presunção; arrogância 6 coração 7 crist. fé 8 crist. doutrina. 〈φρονέω〉</p></section></article>\n<article id=\"entry-dgp-43055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 849 na letra φ · nº geral 43055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de pensar; pensamento; desígnio; aspiração 2 percepção pela inteligência; sentimento; compreensão de algo 3 julgamento; apreciação 4 inteligência; razão; sensatez; prudência 5 inteligência ou sabedoria divina 6 orgulho; arrogância; soberba 7 crist. fé; crença. 〈φρονέω〉</p></section></article>\n<article id=\"entry-dgp-43056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρονητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 850 na letra φ · nº geral 43056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φρονέω.</p></section></article>\n<article id=\"entry-dgp-43057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνιμος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 851 na letra φ · nº geral 43057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 que tem bom senso; sensato; prudente 2 que está no seu juízo; que é senhor de si; lúcido ♦ τὸ φρόνιμον 3 inteligência; sensatez; prudência 4 lucidez. 〈φρήν〉</p></section></article>\n<article id=\"entry-dgp-43058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρονίμως</h1><div class=\"entry-meta\"><span>DGP · ordem 852 na letra φ · nº geral 43058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com sensatez ou com prudência.</p></section></article>\n<article id=\"entry-dgp-43059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 853 na letra φ · nº geral 43059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteligência; bom senso; senzatez, reflexão. 〈φρήν〉</p></section></article>\n<article id=\"entry-dgp-43060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρονούντως</h1><div class=\"entry-meta\"><span>DGP · ordem 854 na letra φ · nº geral 43060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com bom senso; sensatamente; com prudência.</p></section></article>\n<article id=\"entry-dgp-43061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 855 na letra φ · nº geral 43061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐφρόντιζον, fut. φροντιῶ, aor. ἐφρόντισα, perf. πεφρόντικα; m.-q.-perf. ἐπεφροντίκειν, perf. pas. πεφρόντισμαι) 1 pensar; meditar; refletir em algo, ac. 2 inquietar-se; preocupar-se com algo ou alguém, gen. ou περί, ὑπέρ e gen.: σοῦ δ᾽ οὐ φροντιῶ ar. não me ocuparei de ti, μηδὲν ὅρκου φροντίσῃς ar. não te preocupes com teu juramento, σμικρὸν, σμικρὰ φρ. ocupar-se ou preocupar-se pouco, ὀλίγον ou βραχὺ φροντίζειν preocupar-se pouco, φροντίζεσθ᾽ ὡς πλείοσιν μαχούμενοι sóf. prestai atenção porque vos será necessário lutar contra adversários mais numerosos, ἐφρόντιζε ἱστορέων her. preocupava-se em buscar saber, οὐδὲν ἐφρόντιζεν ἐπιορκῶν dem. não se inquietava de perjurar, οὐ φροντίζει σκληρῶς σε καθήμενον οὕτως ar. não se preocupa de te ver sentado tão desconfortavelmente, φρόντισον pensa nisso! presta atenção! μὴ φροντίσῃς ar. não te inquietes 3 perf. estar preocupado; estar inquieto: τὸ πεφρον­τικός cuidado, preocupação, πεφροντικὸς βλέπειν eur. ter ar preocupado ♦ pas. 4 ser objeto de preocupação; receber cuidados: λόγος πεφροντισμένος d.s. discurso elaborado com cuidado, τροφὴ πεφροντισμένη el. alimento preparado com cuidado. 〈φροντίς〉</p></section></article>\n<article id=\"entry-dgp-43062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 856 na letra φ · nº geral 43062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cuidado; inquietação; preocupação com alguém ou algo, gen. ou περί e gen.: φροντίδα ἔχειν sóf., φροντίδα ποιεῖσθαι d.s. ter preocupação, preocupar-se, φροντίδα παρέχειν τινί ar. dar preocupação a alguém, οὐ φροντὶς Ἱπποκλείδῃ her. não é preocupação para Hipoclides, ἐν φροντίδι εἶναι περί τινος her. estar inquieto com algo, ἐν φροντίδι εἶναι ὅ τι χρὴ ποιεῖν xen. preocupar-se com o que é preciso fazer, ἐν φροντίδι γίγνεσθαι xen. ficar inquieto, ficar preocupado 2 modo de pensar; sentimento 3 objeto de meditação 4 reflexão; pensamento; meditação: δευτέραι φροντίδες σοφώτεραι eur. o segundo pensamento é o mais sensato 5 especulação filosófica. 〈φρήν〉</p></section></article>\n<article id=\"entry-dgp-43063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόντισμα, ατος</h1><div class=\"entry-meta\"><span>DGP · ordem 857 na letra φ · nº geral 43063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(τό) 1 objeto de meditação, de preocupação 2 produto de reflexão; raciocínio; concepção. 〈φροντίζω〉</p></section></article>\n<article id=\"entry-dgp-43064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντιστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 858 na letra φ · nº geral 43064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de φροντίζω.</p></section></article>\n<article id=\"entry-dgp-43065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντιστήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 859 na letra φ · nº geral 43065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lugar de meditação, de especulação filosófica 2 gabinete de trabalho; sala de estudo 3 a Cúria, em Roma 4 crist. mosteiro.</p></section></article>\n<article id=\"entry-dgp-43066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 860 na letra φ · nº geral 43066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pensador; pesquisador de, gen. 2 filósofo 3 curador; administrador. 〈φροντίζω〉</p></section></article>\n<article id=\"entry-dgp-43067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντιστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 861 na letra φ · nº geral 43067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que gosta de meditar; que medita 2 atento; diligente; solícito com algo, περί e gen. ♦ τὸ φροντιστικόν 3 meditação. 〈φροντίζω〉</p></section></article>\n<article id=\"entry-dgp-43068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντιστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 862 na letra φ · nº geral 43068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com cuidado; com solicitude.</p></section></article>\n<article id=\"entry-dgp-43069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροῦδος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 863 na letra φ · nº geral 43069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que está no caminho 2 que partiu 3 que desapareceu; que morreu 4 destruído 5 que se dissipou; que passou. 〈πρὸ ὁδός〉</p></section></article>\n<article id=\"entry-dgp-43070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουρά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 864 na letra φ · nº geral 43070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guarda; vigilância contra alguém, dat. ou ἐπί e ac. 2 Mil. guarda de um posto: φρουρὰν ἄζηλον ὀχήσω ésql. suportarei uma guarda pouco invejável, i. e., passarei lá tristes dias 3 turno de guarda 4 posto de guarda 5 guarnição; guarda (de fronteira, de cidade) 6 entre os lacedemônios, corpo expedicionário; tropa de guarda; tropa equipada 7 cárcere; prisão. 〈προοράω〉</p></section></article>\n<article id=\"entry-dgp-43071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουραρχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 865 na letra φ · nº geral 43071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">função ou posto de comandante do lugar. 〈φρούραρχος〉</p></section></article>\n<article id=\"entry-dgp-43072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρούραρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 866 na letra φ · nº geral 43072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandante de um posto, de uma tropa de guarda. 〈φρουρά, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-43073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 867 na letra φ · nº geral 43073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φρουρήσω, aor. ἐφρούρησα, perf. desus.) 1 montar guarda; estar como sentinela em algum lugar, ἐν e dat., περί e ac.: οἱ φροροῦντες xen. aqueles que vigiam, os guardas, ou plat. os guarda-costas 2 guardar; vigiar, ac.; vigiar para que, ὅπως 3 sitiar 4 defender por meio de uma guarnição, de uma tropa, de uma frota 5 pôr uma guarnição em; cercar com guardas; proteger por meio de guardas; defender, ac. 6 vigiar; prestar atenção a, ac. ou ἐπί e dat.: φρ. χρέος sóf. cumprir seu dever, φρουρεῖν ὄμμ᾽ ἐπὶ σῷ καιρῷ sóf. ficar de olho no que te é oportuno. 〈φρουρά〉</p></section></article>\n<article id=\"entry-dgp-43074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρούρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 868 na letra φ · nº geral 43074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 objeto vigiado, guardado: βουκό­λων φρουρήματα sóf. rebanhos vigiados pelos boiadeiros 2 ação de vigiar; vigilância 3 guarnição; corpo de guarda: φρούρημα ἔχειν eur. montar guarda. 〈φρουρέω〉</p></section></article>\n<article id=\"entry-dgp-43075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρούριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 869 na letra φ · nº geral 43075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 posto de guarda 2 cidadela; fortaleza 3 prisão 4 guarnição. 〈φρουρός〉</p></section></article>\n<article id=\"entry-dgp-43076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 870 na letra φ · nº geral 43076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barco que escolta outro; barco guarda-costa. 〈φρουρός〉</p></section></article>\n<article id=\"entry-dgp-43077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρουρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 871 na letra φ · nº geral 43077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guarda; sentinela 2 pl. guarnição.</p></section></article>\n<article id=\"entry-dgp-43078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρύαγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 872 na letra φ · nº geral 43078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relincho 2 comportamento arrogante; arrogância; orgulho. 〈φρυάσσω〉</p></section></article>\n<article id=\"entry-dgp-43079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυαγματίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 873 na letra φ · nº geral 43079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) orgulhoso; arrogante; soberbo. 〈φρύαγμα〉</p></section></article>\n<article id=\"entry-dgp-43080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 874 na letra φ · nº geral 43080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 relinchar em direção a algo, ἐπί, πρός e ac. 2 (galo) cocoricar 3 (pessoa) ser altivo, insolente 4 orgulhar-se de algo, ἐπί e dat.</p></section></article>\n<article id=\"entry-dgp-43081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυγανισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 875 na letra φ · nº geral 43081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de colher gravetos. 〈φρύγω〉</p></section></article>\n<article id=\"entry-dgp-43082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρύγανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 876 na letra φ · nº geral 43082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gravetos; lenha seca para queimar. 〈φρύγω〉</p></section></article>\n<article id=\"entry-dgp-43083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φρυγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 877 na letra φ · nº geral 43083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Frígia, região da Ásia Menor. 〈Φρύξ〉</p></section></article>\n<article id=\"entry-dgp-43084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φρύγιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 878 na letra φ · nº geral 43084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον da Frígia; frígio. 〈Φρύξ〉</p></section></article>\n<article id=\"entry-dgp-43085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρύγω</h1><div class=\"entry-meta\"><span>DGP · ordem 879 na letra φ · nº geral 43085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. φρύξω, aor. ἔφρυξα, perf. desus.; pas. aor.1 ἐφρύχθην, aor.2 ἐφρύγην, perf. πέφρυγμαι) grelhar; assar; queimar.</p></section></article>\n<article id=\"entry-dgp-43086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυκτός, ή, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 880 na letra φ · nº geral 43086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assado; grelhado ♦ ὁ φρυκτός 2 archote ou tocha para sinais noturnos 3 sinal de fogo 4 fava grelhada para votar, fazer sorteio ou interrogar o oráculo. 〈φρύγω〉</p></section></article>\n<article id=\"entry-dgp-43087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυκτωρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 881 na letra φ · nº geral 43087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sinalizar por meio de fogos noturnos; fazer sinais de fogo. 〈φρυκτωρός〉</p></section></article>\n<article id=\"entry-dgp-43088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυκτωρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 882 na letra φ · nº geral 43088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sinalização com fogo; sinal de fogo. 〈φρυκτωρός〉</p></section></article>\n<article id=\"entry-dgp-43089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυκτώριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 883 na letra φ · nº geral 43089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">torre para emissão de sinais de fogo. 〈φρυκτωρός〉</p></section></article>\n<article id=\"entry-dgp-43090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρυκτωρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 884 na letra φ · nº geral 43090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sentinela encarregada de observar ou de emitir os sinais de fogo. 〈φρυκτός, οὖρος〉</p></section></article>\n<article id=\"entry-dgp-43091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 885 na letra φ · nº geral 43091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sapo. 〈φρῦνος〉</p></section></article>\n<article id=\"entry-dgp-43092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρῦνος, ου (ο, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 886 na letra φ · nº geral 43092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sapo.</p></section></article>\n<article id=\"entry-dgp-43093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φρύξ, Φρυγός</h1><div class=\"entry-meta\"><span>DGP · ordem 887 na letra φ · nº geral 43093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 da Frigia; frígio ♦ οἱ Φρῦγες 2 os frígios, partic. os troianos.</p></section></article>\n<article id=\"entry-dgp-43094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 888 na letra φ · nº geral 43094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interj. (de desgosto ou desdém) fuh!</p></section></article>\n<article id=\"entry-dgp-43095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φύγαδε</h1><div class=\"entry-meta\"><span>DGP · ordem 889 na letra φ · nº geral 43095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em fuga. 〈φυγή, -δε〉</p></section></article>\n<article id=\"entry-dgp-43096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγαδευτήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 890 na letra φ · nº geral 43096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lugar de refúgio; lugar de asilo. 〈φυγαδεύω〉</p></section></article>\n<article id=\"entry-dgp-43097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγαδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 891 na letra φ · nº geral 43097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expulsar; banir; exilar 2 intr. ser banido, ser exilado ♦ pas. οἱ πεφυγαδευμένοι 3 os banidos, os exilados. 〈φυγάς〉</p></section></article>\n<article id=\"entry-dgp-43098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγαδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 892 na letra φ · nº geral 43098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 referente ao exílio ou aos exilados ♦ οἱ φυγαδικοί e τὸ φυγαδικόν 2 os exilados; os banidos. 〈φυγάς〉</p></section></article>\n<article id=\"entry-dgp-43099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγαδοθήρας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 893 na letra φ · nº geral 43099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que acossa ou persegue os exilados. 〈φυγάς, θηράω〉</p></section></article>\n<article id=\"entry-dgp-43100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φυγαίχμης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 894 na letra φ · nº geral 43100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que foge das lanças ou dos combates; covarde. 〈φεύγω, αἰχμή〉</p></section></article>\n";
